def apply_printed_numeric_values(card_data: dict) -> dict:
    """Apply exact printed prices/Strength/placement without guessing effects."""
    cards = card_data.get("cards", ())
    if {card.get("id") for card in cards} != CANONICAL_CARD_IDS:
        return card_data

    result = deepcopy(card_data)
    for card in result["cards"]:
        values = PRINTED_STAT_OVERRIDES.get(card["id"])
        if not values:
            continue
        card.update(deepcopy(values))
        if card["type"] == "hero":
            card["modes"]["force"]["command_cost"] = card["hero_force_command_cost"]
            card["modes"]["name"]["command_cost"] = card["hero_name_command_cost"]
    return result
